import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { prompts } from "./gate-prompts.mjs";
import { kafkaTerms } from "./kafka-terms.mjs";
import { arqTerms } from "./arq-terms.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));
const outRoot = path.resolve(here, "../data/gates");

function hash32(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  }
  return h >>> 0;
}

function norm(s) {
  return String(s).trim().replace(/\s+/g, " ").toLowerCase();
}

function item(q, correct, wrongs, w, tag) {
  const raw = [correct, ...wrongs.slice(0, 3)];
  const seen = new Set();
  const unique = [];
  for (const o of raw) {
    const k = norm(o);
    if (!k || seen.has(k)) continue;
    seen.add(k);
    unique.push(String(o).trim());
  }
  if (unique.length !== 4) {
    throw new Error(`options ≠ 4 (${tag}): ${unique.length} — ${q}`);
  }
  const rot = hash32(`${q}|${tag}|${correct}`) % 4;
  const o = unique.slice(rot).concat(unique.slice(0, rot));
  const a = o.findIndex((x) => norm(x) === norm(correct));
  if (a < 0) throw new Error(`correct missing (${tag}): ${q}`);
  return { q, o, a, w, t: tag };
}

function expandAsk(ask) {
  const a = String(ask).replace(/\?+$/, "").trim();
  return [
    `${a}?`,
    `${a} — verdade ou mito?`,
    `${a} — o que acontece de verdade?`,
    `Na prática: ${a}?`,
    `${a} — como funciona?`,
    `Se perguntarem: ${a}?`,
    `${a} — o que vale aqui?`,
  ];
}

function stemsFor(f, lessonName, prompt, track) {
  if (Array.isArray(f.qs) && f.qs.length) return f.qs;
  if (track === "arquitetura") {
    throw new Error(
      `${lessonName}/${f.tag}: Arquitetura exige qs escritas à mão (7 perguntas inteiras). expandAsk cola sufixo em fragmento.`,
    );
  }
  const ask = f.ask || prompt?.[0];
  if (!ask) {
    throw new Error(`${lessonName}/${f.tag}: falta pergunta (qs ou ask)`);
  }
  return expandAsk(ask);
}

function pickWrongs(f, facts, prompt, wi, track) {
  if (Array.isArray(f.wrongs) && f.wrongs.length >= 3) {
    return f.wrongs.slice(0, 3).map((s) => String(s).trim());
  }
  if (track === "arquitetura") {
    throw new Error(
      `${f.tag}: Arquitetura exige 3 wrongs do próprio fact. Sem isso o gerador puxaria mitos de outro tag.`,
    );
  }
  const mine = prompt?.[1] ? [prompt[1]] : f.x ? [f.x] : [];
  const others = facts
    .filter((o) => o !== f)
    .flatMap((o) => {
      const p = o._prompt;
      const list = [];
      if (p?.[1]) list.push(p[1]);
      if (o.x) list.push(o.x);
      if (Array.isArray(o.wrongs)) list.push(...o.wrongs);
      return list;
    });
  const pool = [];
  const seen = new Set();
  for (const s of [...mine, ...others]) {
    const t = String(s).trim();
    const k = norm(t);
    if (!k || k === norm(f.c) || seen.has(k)) continue;
    seen.add(k);
    pool.push(t);
  }
  if (pool.length < 3) {
    throw new Error(`${f.tag}: só ${pool.length} erros relacionados`);
  }
  const own = mine[0];
  const rest = own ? pool.filter((m) => m !== own) : pool;
  const out = own ? [own] : [];
  let i = wi;
  while (out.length < 3) {
    const m = rest[i % rest.length];
    if (!out.includes(m)) out.push(m);
    i += 1;
    if (i > wi + rest.length + 5) break;
  }
  if (out.length < 3) {
    throw new Error(`${f.tag}: não deu para montar 3 erros`);
  }
  return out;
}

function bank(name, facts, track, slug) {
  const lessonPrompts = prompts[track]?.[slug] ?? {};
  const annotated = facts.map((f) => ({
    ...f,
    _prompt: lessonPrompts[f.tag],
  }));
  const questions = [];
  const seen = new Set();
  let wi = 0;
  for (const f of annotated) {
    for (const q of stemsFor(f, name, f._prompt, track)) {
      if (seen.has(q)) continue;
      seen.add(q);
      const polish = track === "kafka" ? kafkaTerms : arqTerms;
      questions.push(
        item(
          polish(q),
          polish(f.c),
          pickWrongs(f, annotated, f._prompt, wi, track).map(polish),
          polish(f.w),
          f.tag,
        ),
      );
      wi += 1;
    }
  }
  if (questions.length < 100) {
    throw new Error(`${name}: only ${questions.length} questions`);
  }
  return questions.slice(0, 108);
}

function write(track, slug, questions) {
  const dir = path.join(outRoot, track);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(
    path.join(dir, `${slug}.json`),
    JSON.stringify({ questions }, null, 2) + "\n",
  );
}

