function emit(track, dict) {
  for (const [slug, spec] of Object.entries(dict)) {
    const questions = bank(spec.name, spec.facts, track, slug);
    write(track, slug, questions);
    console.log(track, slug, questions.length);
  }
}

const ANALOGY_TAGS = new Set([
  "post-it",
  "foto",
  "geladeira",
  "loja",
  "Ana",
  "caixa",
  "analogia",
  "etiqueta",
  "dois caixas",
  "fatia",
  "pior",
  "vazamento",
  "busca",
  "bulkhead",
  "ferramenta",
  "REST",
]);

function polishQuestion(q, fn) {
  return {
    ...q,
    q: fn(q.q),
    o: q.o.map(fn),
    w: fn(q.w),
  };
}

function uniqueOptions(q) {
  return new Set(q.o.map((o) => String(o).trim().toLowerCase())).size === 4;
}

function patchAnalogy() {
  for (const [slug, spec] of Object.entries(arq)) {
    const file = path.join(outRoot, "arquitetura", `${slug}.json`);
    if (!fs.existsSync(file)) continue;
    const existing = JSON.parse(fs.readFileSync(file, "utf8"));
    const fresh = bank(spec.name, spec.facts, "arquitetura", slug);
    const freshByTag = new Map();
    for (const q of fresh) {
      if (!freshByTag.has(q.t)) freshByTag.set(q.t, []);
      freshByTag.get(q.t).push(q);
    }
    const iByTag = {};
    existing.questions = existing.questions.map((q) => {
      let next = q;
      if (ANALOGY_TAGS.has(q.t)) {
        const bucket = freshByTag.get(q.t) || [];
        const idx = iByTag[q.t] ?? 0;
        iByTag[q.t] = idx + 1;
        next = bucket[idx] ?? polishQuestion(q, arqTerms);
      } else {
        next = polishQuestion(q, arqTerms);
      }
      if (!uniqueOptions(next)) {
        const bucket = freshByTag.get(q.t) || [];
        const fallback = bucket[0];
        if (fallback && uniqueOptions(fallback)) next = fallback;
      }
      return next;
    });
    write("arquitetura", slug, existing.questions);
    console.log("patched", slug, existing.questions.length);
  }
  for (const slug of Object.keys(kafka)) {
    const file = path.join(outRoot, "kafka", `${slug}.json`);
    if (!fs.existsSync(file)) continue;
    const existing = JSON.parse(fs.readFileSync(file, "utf8"));
    existing.questions = existing.questions.map((q) => {
      const next = polishQuestion(q, kafkaTerms);
      return uniqueOptions(next) ? next : q;
    });
    write("kafka", slug, existing.questions);
    console.log("polished kafka", slug, existing.questions.length);
  }
}

const GLUE_STEM_PREFIXES = [
  "O mito é o contrário. ",
  "Se misturarem conceitos: ",
  "Marque a opção verdadeira. ",
  "Entre as opções: ",
  "Qual afirmação está correta? ",
  "O que é verdade? ",
];

function stripGlueStem(prompt) {
  let q = String(prompt).trim();
  for (const prefix of GLUE_STEM_PREFIXES) {
    if (q.startsWith(prefix)) {
      q = q.slice(prefix.length).trim();
      break;
    }
  }
  return q;
}

function stripGlueStems() {
  for (const track of ["kafka", "arquitetura"]) {
    const dir = path.join(outRoot, track);
    if (!fs.existsSync(dir)) continue;
    for (const file of fs.readdirSync(dir).filter((f) => f.endsWith(".json"))) {
      const full = path.join(dir, file);
      const json = JSON.parse(fs.readFileSync(full, "utf8"));
      let changed = 0;
      for (const q of json.questions ?? []) {
        const next = stripGlueStem(q.q);
        if (next !== q.q) {
          q.q = next;
          changed += 1;
        }
      }
      if (changed) {
        fs.writeFileSync(full, JSON.stringify(json, null, 2) + "\n");
      }
      console.log("stems", track, file, changed);
    }
  }
}

function patchTagged(track, slug, tags) {
  const catalog = track === "kafka" ? kafka : arq;
  const spec = catalog[slug];
  if (!spec) throw new Error(`unknown lesson ${track}/${slug}`);
  const fresh = bank(spec.name, spec.facts, track, slug);
  const byTag = new Map();
  for (const q of fresh) {
    if (!tags.has(q.t)) continue;
    if (!byTag.has(q.t)) byTag.set(q.t, []);
    byTag.get(q.t).push(q);
  }
  const file = path.join(outRoot, track, `${slug}.json`);
  const existing = JSON.parse(fs.readFileSync(file, "utf8"));
  const iByTag = {};
  existing.questions = existing.questions.map((q) => {
    if (!tags.has(q.t)) return q;
    const bucket = byTag.get(q.t) || [];
    const idx = iByTag[q.t] ?? 0;
    iByTag[q.t] = idx + 1;
    return bucket[idx] ?? q;
  });
  write(track, slug, existing.questions);
  console.log("patched tags", track, slug, [...tags].join(","));
}

if (process.argv.includes("--patch-analogy")) {
  patchAnalogy();
  console.log("analogy families patched");
} else if (process.argv.includes("--patch-stems")) {
  patchTagged("kafka", "topico", new Set(["CLI"]));
  stripGlueStems();
  console.log("stems stripped, CLI family patched");
} else {
  emit("kafka", kafka);
  emit("arquitetura", arq);
  console.log("gate banks written");
}
